function regressionFor(type){const data=allAttempts().filter(a=>a.prediction&&a.prediction.type===type&&Number.isFinite(a.prediction.raw)&&Number.isFinite(a.score));if(!data.length)return {n:0,a:0,b:1,mae:null,sd:null,method:'Uncalibrated'};const errors=data.map(d=>d.score-d.prediction.raw),mae=errors.reduce((s,x)=>s+Math.abs(x),0)/errors.length;const meanErr=errors.reduce((s,x)=>s+x,0)/errors.length;let a=meanErr,b=1,method='Mean-bias correction';if(data.length>=8){const mx=data.reduce((s,d)=>s+d.prediction.raw,0)/data.length,my=data.reduce((s,d)=>s+d.score,0)/data.length;const den=data.reduce((s,d)=>s+(d.prediction.raw-mx)**2,0);if(den>1e-6){b=data.reduce((s,d)=>s+(d.prediction.raw-mx)*(d.score-my),0)/den;a=my-b*mx;method='Linear calibration';}}const calibratedErrors=data.map(d=>d.score-(Number.isFinite(d.prediction.calibrated)?d.prediction.calibrated:d.prediction.raw));const meanCal=calibratedErrors.reduce((s,x)=>s+x,0)/calibratedErrors.length;const sd=calibratedErrors.length>1?Math.sqrt(calibratedErrors.reduce((s,x)=>s+(x-meanCal)**2,0)/(calibratedErrors.length-1)):null;return {n:data.length,a,b,mae,sd,method};}
function getSchedule(type,id){return (type==='QPT'?QPT:QFT).find(x=>x.id===id)||null}
function predict(type,id){const sched=getSchedule(type,id);if(!sched)return null;let chapters=type==='QPT'?sched.chapterIds.map(x=>CHAP_BY_ID[x]).filter(Boolean):CORE_CHAPTERS;chapters=chapters.filter(c=>c.status==='core');const baseline=globalBaseline();const per=chapters.map(ch=>{const s=chapterStats(ch);const m=s.mastery==null?baseline:s.mastery;return {chapter:ch,mastery:m,count:s.count,observations:s.observations,transferCount:s.transferCount,confidence:s.confidence,meanMarksPerQ:state.settings.correctMarks*m/100};});const qn=type==='QPT'?Number(state.settings.blockQuestions):Number(state.settings.blockQuestions);const raw=per.length?qn*per.reduce((s,p)=>s+p.meanMarksPerQ,0)/per.length:0;const cal=regressionFor(type);const calibrated=cal.n>=2?cal.a+cal.b*raw:raw;const residual=cal.sd;const half=cal.n>=8&&residual!=null?Math.max(10,1.65*residual):cal.n>=4&&residual!=null?Math.max(15,1.5*residual):Math.max(18,qn*.3);const dataCount=per.filter(p=>p.observations>0).length;const coverage=per.length?dataCount/per.length:0;let confidence=cal.n>=8&&coverage>.75?'High':cal.n>=4&&coverage>.5?'Medium':'Low';if(coverage<.3)confidence='Low';const clipped=Math.max(-qn,Math.min(qn*4,calibrated));return {type,id,sched,chapters:per,raw,calibrated:clipped,lower:Math.max(-qn,clipped-half),upper:Math.min(qn*4,clipped+half),half,covered:dataCount,coverage,confidence,calibration:cal,questionCount:qn};}
function nextSchedule(){const completed=new Set(allAttempts().map(a=>String(a.testId||'').toUpperCase()));const doneQpt=QPT.map(q=>Number(q.id.split('-')[1])).filter(n=>completed.has(`QPT-${n}`));if(doneQpt.length){for(let n=Math.max(...doneQpt)+1;n<=16;n++){const q=QPT.find(x=>x.id===`QPT-${n}`);if(q&&!completed.has(q.id))return q;}}const today=dateTimeISO();const remaining=[...QPT,...QFT].filter(s=>!completed.has(s.id.toUpperCase()));const upcoming=remaining.filter(s=>s.date>=today).sort((a,b)=>a.date.localeCompare(b.date));if(upcoming.length)return upcoming[0];return remaining.sort((a,b)=>b.date.localeCompare(a.date))[0]||null}
function aggregateErrorStats(){const map={};state.attempts.forEach(t=>{(t.chapterResults||[]).forEach(r=>{const errors=r.errorCounts||{};TAGS.forEach(tag=>map[tag]=(map[tag]||0)+(Number(errors[tag])||0));(r.questionErrors||[]).forEach(e=>{const tg=TAGS.includes(e.category)?e.category:'unclassified';map[tg]=(map[tg]||0)+1;});});(t.questionErrors||[]).forEach(e=>{const tag=TAGS.includes(e.category)?e.category:'unclassified';map[tag]=(map[tag]||0)+1;});});return map}
function predictionMetrics(type=null){const rows=allAttempts().filter(a=>a.prediction&&Number.isFinite(a.score)&&(!type||a.prediction.type===type));const rawRows=rows.filter(a=>Number.isFinite(a.prediction.raw));const rawErrors=rawRows.map(a=>a.score-a.prediction.raw);const stat=errs=>errs.length?{mae:errs.reduce((s,e)=>s+Math.abs(e),0)/errs.length,bias:errs.reduce((s,e)=>s+e,0)/errs.length,rmse:Math.sqrt(errs.reduce((s,e)=>s+e*e,0)/errs.length),maxAbs:Math.max(...errs.map(Math.abs))}:{mae:null,bias:null,rmse:null,maxAbs:null};const raw=stat(rawErrors);const calibratedRows=rows.filter(a=>Number.isFinite(a.prediction.calibrated));const calibratedErrors=calibratedRows.map(a=>a.score-a.prediction.calibrated);const calibrated=stat(calibratedErrors);const bounds=rawRows.filter(a=>Number.isFinite(a.prediction.lower)&&Number.isFinite(a.prediction.upper));const coverage=bounds.length?100*bounds.filter(a=>a.score>=a.prediction.lower&&a.score<=a.prediction.upper).length/bounds.length:null;return {n:rawRows.length,...raw,coverage,calibratedN:calibratedRows.length,calibratedMae:calibrated.mae,calibratedBias:calibrated.bias,calibratedRmse:calibrated.rmse,calibratedMaxAbs:calibrated.maxAbs};}
function subjectStats(subject){const arr=CORE_CHAPTERS.filter(c=>c.subject===subject).map(chapterStats);const tested=arr.filter(s=>s.observations);const avg=tested.length?tested.reduce((s,x)=>s+x.mastery,0)/tested.length:null;return {count:arr.length,tested:tested.length,avg,chapters:arr}}
function ratingLabel(score){if(score==null)return 'UNRATED';if(score<40)return 'RECRUIT';if(score<55)return 'BRONZE';if(score<70)return 'SILVER';if(score<80)return 'GOLD';if(score<90)return 'PLATINUM';return 'DIAMOND'}
function statsForDashboard(){const comp=allAttempts();const last=comp.slice(-1)[0];const preds=comp.filter(a=>a.prediction);const errors=preds.map(a=>a.score-a.prediction.raw);const mae=errors.length?errors.reduce((s,e)=>s+Math.abs(e),0)/errors.length:null;const tested=CHAPTERS.filter(c=>chapterStats(c).observations>0).length;const avg=globalBaseline();const xp=comp.reduce((sum,a)=>{const cats=Math.max((a.questionErrors||[]).length,(a.chapterResults||[]).reduce((t,r)=>t+Math.max((r.questionErrors||[]).length,Object.values(r.errorCounts||{}).reduce((z,v)=>z+(Number(v)||0),0)),0));return sum+25+Math.min(20,cats*2)+Math.min(10,(a.chapterResults||[]).length*2)},0);const ranks=[{name:'Recruit',min:0,next:150},{name:'Bronze',min:150,next:400},{name:'Silver',min:400,next:800},{name:'Gold',min:800,next:1500},{name:'Platinum',min:1500,next:2500},{name:'Diamond',min:2500,next:5000}];const rank=[...ranks].reverse().find(r=>xp>=r.min)||ranks[0];const nextRank=ranks.find(r=>r.min>xp);const days=[...new Set(comp.map(a=>a.date).filter(Boolean))].sort();let streak=0;if(days.length){const dayMs=86400000;let target=new Date(dateTimeISO()+'T12:00:00').getTime();let lastMs=new Date(days[days.length-1]+'T12:00:00').getTime();if(target-lastMs<=dayMs*1.6){streak=1;for(let i=days.length-2;i>=0;i--){const cur=new Date(days[i]+'T12:00:00').getTime();const next=new Date(days[i+1]+'T12:00:00').getTime();if(next-cur<=dayMs*1.1)streak++;else break;}}}return {comp,last,preds,mae,tested,avg,unscored:state.attempts.length-comp.length,xp,rank,nextRank,streak}}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.style.opacity='1';el.style.transform='translate(-50%,0)';clearTimeout(toast._t);toast._t=setTimeout(()=>{el.style.opacity='0';el.style.transform='translate(-50%,20px)'},2900)}
const viewInfo={dashboard:['PERFORMANCE INTELLIGENCE / 01','Command center','Every test is data. Every weakness has a price.'],chapters:['MASTERY MAP / 02','Chapter map','Find your strongest maps, expensive mistakes, and highest-return drills.'],historical:['PYQ INTELLIGENCE / 03','Historical PYQ intelligence','Explore verified Physics, Chemistry, and Mathematics E–M–T–O trends from 2019–2025, alongside source mentorship notes.'],tests:['EXECUTION LOG / 04','Test history','One clean ledger for chapter tests, part tests, checkpoints, and mocks.'],forecasts:['PREDICTION ENGINE / 05','Forecast lab','Forecast first. Test later. Measure every prediction error.'],chatbot:['AI COACH / 06','AI Coach','JEE-aware study coach. Paste your API key and ask about weak chapters, strategy, or any concept.'],data:['SYSTEM CONTROL / 06','Data & settings','Structured import, transparent assumptions, export, and recovery.']};
function switchView(view){if(!viewInfo[view])return;currentView=view;state.ui.view=view;document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id===`view-${view}`));document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view));document.getElementById('pageEyebrow').textContent=viewInfo[view][0];document.getElementById('pageTitle').textContent=viewInfo[view][1];document.getElementById('pageSubtitle').textContent=viewInfo[view][2];persist();renderCurrent();window.scrollTo({top:0,behavior:'smooth'});}
function navWiring(){document.getElementById('quickLog').addEventListener('click',openTestModal);}
document.addEventListener('click',e=>{const button=e.target.closest('button[data-view]');if(!button)return;const view=button.dataset.view;if(!viewInfo[view])return;e.preventDefault();switchView(view);});
function renderCurrent(){if(currentView==='dashboard')renderDashboard();else if(currentView==='chapters')renderChapters();else if(currentView==='historical')renderHistorical();else if(currentView==='tests')renderTests();else if(currentView==='forecasts')renderForecasts();else if(currentView==='chatbot')renderChatbot();else renderData();}
function scorePill(score,max){return `<span class="tag ${score>=.8*max?'green':score>=.55*max?'purple':'amber'}">${fmt(score,1)} / ${fmt(max,0)}</span>`}
function renderDashboard(){const root=document.getElementById('view-dashboard'),d=statsForDashboard(),qpt=nextSchedule(),chapStats=CORE_CHAPTERS.map(chapterStats),priority=chapStats.filter(s=>s.observations).sort((a,b)=>b.priority-a.priority).slice(0,5),subjectCards=SUBJECTS.map(s=>({s,...subjectStats(s)}));const latest=d.last;const forecast=qpt?predict(qpt.id.startsWith('QPT')?'QPT':'QFT',qpt.id):null;const cntExtra=EXTRA_CHAPTERS.length;
root.innerHTML=`<div class="card hero"><div class="hero-content"><div class="hero-chip"><span>✦</span>YOUR TRAINING ENVIRONMENT · ${esc(ratingLabel(d.comp.length?d.avg:null))} · ${d.xp} XP</div><h2>${d.comp.length?'The next mark is hiding in your data.':'Build your baseline. Then break it.'}</h2><p>${d.comp.length?`You have logged ${d.comp.length} completed test${d.comp.length===1?'':'s'}. Keep every attempt tied to its raw outcomes so Loadout can learn what transfers to mixed tests.`:'No results have been entered yet. Start with the next test analysis: import structured feedback from ChatGPT or log a test manually. No fake demo scores, no made-up history.'}</p><div class="hero-actions"><button class="btn primary" data-action="log">＋ Log a test</button><button class="btn" data-action="import">⇄ Import ChatGPT data</button><button class="btn" data-action="forecast">⌁ Open forecast lab</button></div></div></div>
<div class="grid stats">
<div class="card stat-card" style="--glow:var(--purple)"><span class="stat-icon">▦</span><div class="stat-label">Chapters with evidence</div><div class="stat-value">${d.tested}<span class="muted" style="font-size:15px;font-weight:600"> / ${CHAPTERS.length}</span></div><div class="stat-foot">${CHAPTERS.length-d.tested} not tested yet</div><div class="progress" style="margin-top:12px"><span style="width:${100*d.tested/CHAPTERS.length}%"></span></div></div>
<div class="card stat-card" style="--glow:var(--mint)"><span class="stat-icon">↗</span><div class="stat-label">Chapter-test baseline</div><div class="stat-value">${d.comp.length?fmt(d.avg,1):'—'}<span class="muted" style="font-size:14px"> / 100</span></div><div class="stat-foot">Mean of recorded chapter-level scaled results</div></div>
<div class="card stat-card" style="--glow:var(--amber)"><span class="stat-icon">◎</span><div class="stat-label">Latest completed test</div><div class="stat-value">${latest?fmt(latest.score,0):'—'}<span class="muted" style="font-size:14px"> / ${latest?fmt(latest.maxMarks,0):'—'}</span></div><div class="stat-foot">${latest?`${esc(latest.title)} · ${dateFmt(latest.date)}`:'Your first result will appear here'}</div></div>
<div class="card stat-card" style="--glow:var(--blue)"><span class="stat-icon">⌁</span><div class="stat-label">Forecast mean absolute error</div><div class="stat-value">${d.mae==null?'—':fmt(d.mae,1)}<span class="muted" style="font-size:14px"> marks</span></div><div class="stat-foot">${d.preds.length?`${d.preds.length} scored test${d.preds.length===1?'':'s'} with saved forecast`:'Save forecasts before tests to measure accuracy'}</div></div>
</div>
<div class="two-col"><div class="card pad"><div class="card-header"><div><h2>Subject telemetry</h2><p class="sub">Regularized chapter estimates · evidence coverage matters</p></div><span class="tag purple">3 SUBJECTS</span></div><div class="bar-list">${subjectCards.map(x=>`<div><div class="bar-row"><div class="bar-name"><span class="subject-color" style="background:${SUBJECT_META[x.s].color}"></span>${x.s}</div><div class="progress"><span style="width:${Math.max(0,Math.min(100,x.avg||0))}%;background:${SUBJECT_META[x.s].color}"></span></div><div class="bar-value">${x.avg==null?'—':fmt(x.avg,1)}</div></div><div class="tiny" style="margin:5px 0 0 2px">${x.tested}/${x.count} chapters have data${x.avg==null?' · not rated':` · ${ratingLabel(x.avg)}`}</div></div>`).join('')}</div><div class="divider"></div><div class="notice">The chapter baseline is not a JEE percentile. It's your net-mark percentage across recorded chapter-level tests, regularized for limited evidence.</div></div>
<div class="card pad"><div class="card-header"><div><h2>Next on the schedule</h2><p class="sub">Based on the uploaded October Batch schedule</p></div><span class="tag ${qpt&&qpt.kind==='checkpoint'?'amber':'purple'}">${qpt?esc(qpt.id):'COMPLETE'}</span></div>${qpt?`<div class="eyebrow" style="color:var(--muted)">${scheduleDateLabel(qpt)} · ${qpt.kind==='checkpoint'?'PYQ CHECKPOINT':qpt.phase?esc(qpt.phase.toUpperCase()):'PART TEST'}</div><h3 style="font-size:24px;margin:7px 0 4px">${esc(qpt.name)}</h3><p class="sub" style="margin-bottom:16px">${qpt.label?esc(qpt.label):qpt.subjects?`${qpt.chapterIds.length} unique mapped chapters · three subjects`:esc(qpt.note||'Full syllabus')}</p>${forecast?`<div class="forecast-score" style="font-size:43px">${fmt(forecast.calibrated,1)}<em> / ${state.settings.blockQuestions*state.settings.correctMarks}</em></div><div class="tiny" style="margin-top:6px">Current estimate · ${forecast.confidence.toLowerCase()} confidence</div>`:`<div class="notice">No upcoming schedule item could be resolved.</div>`}<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:16px"><button class="btn primary" data-action="forecast-schedule" data-id="${qpt.id}">Build forecast ↗</button><button class="btn" data-action="log-schedule" data-id="${qpt.id}">Log result</button></div>`:`<div class="empty"><strong>All scheduled tests have entries</strong>Keep adding future QFT tests as they become available.</div>`}</div></div>
<div class="two-col"><div class="card pad"><div class="card-header"><div><h2>Highest-return training targets</h2><p class="sub">Heuristic priority = recoverable marks estimate per intervention hour</p></div><button class="btn small" data-action="chapters">Full chapter map ↗</button></div>${priority.length?`<div class="chapter-list">${priority.map(s=>chapterRowHtml(s)).join('')}</div>`:`<div class="empty"><strong>Nothing to rank yet</strong>Import a chapter result or log a chapterwise test to unlock weakness prioritization.</div>`}</div>
<div class="card pad"><div class="card-header"><div><h2>Recent executions</h2><p class="sub">Last five completed results</p></div><button class="btn small" data-action="tests">View history ↗</button></div>${d.comp.length?`<div class="chapter-list">${d.comp.slice(-5).reverse().map(a=>`<div class="chapter-row"><div><div class="chapter-name">${esc(a.title||a.testId)}</div><div class="chapter-meta"><span class="tag">${esc(a.type)}</span><span class="tiny">${dateFmt(a.date)}</span>${a.prediction?`<span class="tag ${a.score-a.prediction.raw>=0?'green':'red'}">Δ ${a.score-a.prediction.raw>=0?'+':''}${fmt(a.score-a.prediction.raw,1)}</span>`:''}</div></div><div class="chapter-score"><strong>${fmt(a.score,0)}</strong><small>/ ${fmt(a.maxMarks,0)}</small></div></div>`).join('')}</div>`:`<div class="empty"><strong>No test history</strong>Your real results will populate this feed.</div>`}</div></div>
<div class="card pad" style="margin-bottom:15px"><div class="card-header"><div><h2>Ranked progression</h2><p class="sub">Cosmetic training XP rewards unique completed test records and explicit diagnostics. It never changes predicted or actual marks.</p></div><span class="tag purple">${esc(d.rank.name.toUpperCase())}</span></div><div class="grid stats metric-three" style="margin-bottom:10px"><div class="stat-card"><div class="stat-label">Training XP</div><div class="stat-value">${d.xp}</div><div class="stat-foot">${d.comp.length} completed unique tests</div></div><div class="stat-card"><div class="stat-label">Current study streak</div><div class="stat-value">${d.streak}<span class="muted" style="font-size:13px"> day${d.streak===1?'':'s'}</span></div><div class="stat-foot">Based on dates with completed tests</div></div><div class="stat-card"><div class="stat-label">Next tier</div><div class="stat-value" style="font-size:24px">${d.nextRank?esc(d.nextRank.name):'MAX'}</div><div class="stat-foot">${d.nextRank?`${Math.max(0,d.nextRank.min-d.xp)} XP to promotion`:'Diamond achieved'}</div></div></div><div class="progress"><span style="width:${d.nextRank?Math.max(0,Math.min(100,100*(d.xp-d.rank.min)/(d.nextRank.min-d.rank.min))):100}%;background:linear-gradient(90deg,var(--purple),var(--mint))"></span></div><div class="tiny" style="margin-top:7px">XP formula: +25 per completed test, +2 per recorded classified error (capped at +20/test), +2 per chapter result (capped at +10/test). This rewards thorough logging, not high marks or guessing.</div></div>
<div class="notice amber"><b>Source note:</b> the PDF lists 96 QCT rows, including chapters marked with an asterisk as beyond JEE Main and a separate “Mathematics in Physics” support row. Loadout keeps every source row and marks those categories instead of deleting them. The resulting core filter is derived from that file and may not match a separately grouped 25/29/29 chapter taxonomy.</div>`;
}
function chapterRowHtml(s){const c=s.chapter;const score=s.mastery;return `<div class="chapter-row"><div><div class="chapter-name">${esc(c.name)}</div><div class="chapter-meta"><span class="tag" style="color:${SUBJECT_META[c.subject].color}">${esc(c.subject)}</span><span class="tag ${pctClass(score)}">${s.count} QCT${s.count===1?'':'s'}${s.transferCount?` + ${s.transferCount} block obs.`:''}</span>${s.trend!=null?`<span class="tag ${s.trend>=0?'green':'red'}">${s.trend>=0?'↑':'↓'} ${fmt(Math.abs(s.trend),1)} pp</span>`:''}</div></div><div class="chapter-score"><strong class="${score>=70?'good':score<50?'warn':''}">${score==null?'—':fmt(score,1)}</strong><small>${s.priority?fmt(s.priority,1)+' priority':'no errors tagged'}</small></div></div>`}
function renderChapters(){const root=document.getElementById('view-chapters');const filtered=CHAPTERS.filter(c=>(chapterSubject==='All'||c.subject===chapterSubject)&&(chapterFilter==='All'||(chapterFilter==='Core'&&c.status==='core')||(chapterFilter==='Extra'&&c.status==='extra')||(chapterFilter==='Support'&&c.status==='support'))&&norm(c.name).includes(norm(chapterSearch)));const order=['Physics','Chemistry','Mathematics'];root.innerHTML=`<div class="card pad"><div class="card-header"><div><h2>83+ chapter performance map</h2><p class="sub">Browse every chapter listed in the QCT schedule; star-marked extras and support topics remain visible.</p></div><span class="tag purple">${CHAPTERS.length} SOURCE ROWS</span></div><div class="filters"><input id="chapterSearch" class="input" placeholder="Search a chapter or topic…" value="${esc(chapterSearch)}"><select id="chapterSubject"><option>All</option>${SUBJECTS.map(s=>`<option ${chapterSubject===s?'selected':''}>${s}</option>`).join('')}</select><select id="chapterFilter"><option value="All" ${chapterFilter==='All'?'selected':''}>All rows</option><option value="Core" ${chapterFilter==='Core'?'selected':''}>Core filter</option><option value="Extra" ${chapterFilter==='Extra'?'selected':''}>Beyond JEE Main *</option><option value="Support" ${chapterFilter==='Support'?'selected':''}>Support topics</option></select><button class="btn" id="clearChapterFilters">Reset</button></div></div><div class="section-head"><div><h2>${filtered.length} chapters</h2><p>Click any chapter to inspect attempts, estimated mastery, error tags and QCT count.</p></div></div>${filtered.length?order.filter(s=>filtered.some(c=>c.subject===s)).map(sub=>`<div class="subject-heading"><span class="subject-color" style="background:${SUBJECT_META[sub].color}"></span>${sub}<span class="count-badge">${filtered.filter(c=>c.subject===sub).length}</span></div><div class="mastery-grid">${filtered.filter(c=>c.subject===sub).map(c=>{const s=chapterStats(c);const mastery=s.mastery;return `<button class="mastery-cell" data-action="chapter-detail" data-id="${c.id}" style="text-align:left;color:var(--text);cursor:pointer"><div class="mc-name" title="${esc(c.name)}">${esc(c.name)} ${c.status==='extra'?'*':''}${c.status==='support'?'·':''}</div><strong class="${mastery==null?'muted':mastery>=70?'good':mastery<50?'warn':''}">${mastery==null?'—':fmt(mastery,1)}</strong><span class="tiny">${s.count} / ${c.tests} planned QCTs${s.transferCount?` · ${s.transferCount} block obs.`:''}</span><div class="progress" style="margin-top:8px"><span style="width:${Math.max(0,Math.min(100,mastery||0))}%;${c.status==='extra'?'background:var(--amber)':''}"></span></div></button>`}).join('')}</div>`).join(''):`<div class="empty"><strong>No matching chapter</strong>Try a different search or reset the filters.</div>`}<div class="notice" style="margin-top:18px">Mastery index = recency-weighted scaled test result, shrunk toward the overall chapter-test baseline using the configured prior strength. An empty cell means no chapter-level evidence exists; it is not a zero score.</div>`;
const si=document.getElementById('chapterSearch');si.addEventListener('input',e=>{chapterSearch=e.target.value;const pos=e.target.selectionStart;renderChapters();const x=document.getElementById('chapterSearch');x.focus();x.setSelectionRange(pos,pos)});document.getElementById('chapterSubject').addEventListener('change',e=>{chapterSubject=e.target.value;renderChapters()});document.getElementById('chapterFilter').addEventListener('change',e=>{chapterFilter=e.target.value;renderChapters()});document.getElementById('clearChapterFilters').addEventListener('click',()=>{chapterSearch='';chapterSubject='All';chapterFilter='All';renderChapters()});}
function renderTests(){const root=document.getElementById('view-tests');const list=state.attempts.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));const filtered=list.filter(a=>testFilter==='All'||a.type===testFilter);const completed=filtered.filter(a=>a.score!==null&&a.score!==undefined);root.innerHTML=`<div class="card pad"><div class="card-header"><div><h2>Test execution ledger</h2><p class="sub">Predictions are linked to actual results by test ID. Forecasts remain frozen after a test is completed.</p></div><button class="btn primary" data-action="log">＋ Log test</button></div><div class="filters"><select id="testFilter"><option>All</option><option ${testFilter==='QCT'?'selected':''}>QCT</option><option ${testFilter==='QPT'?'selected':''}>QPT</option><option ${testFilter==='QFT'?'selected':''}>QFT</option><option ${testFilter==='HFT'?'selected':''}>HFT</option><option ${testFilter==='OTHER'?'selected':''}>OTHER</option></select><span class="pill">${completed.length} completed · ${list.length-completed.length} forecasts awaiting result</span></div></div><div class="section-head"><div><h2>Recorded attempts</h2><p>Score is recalculated from correct and wrong counts; a source-provided score never overrides the arithmetic.</p></div></div>${filtered.length?`<div class="table-wrap"><table><thead><tr><th>Test / date</th><th>Type</th><th>Outcome C/W/U</th><th>Score</th><th>Predicted</th><th>Residual</th><th>Actions</th></tr></thead><tbody>${filtered.map(a=>`<tr><td><strong>${esc(a.title||a.testId)}</strong><div class="tiny">${dateFmt(a.date)} · ${esc(a.testId||'No ID')}</div></td><td><span class="tag">${esc(a.type)}</span></td><td>${a.score==null?'—':`${a.correct}/${a.wrong}/${a.unattempted}`}<div class="tiny">${a.n} questions · ${a.minutes??'—'} min</div></td><td>${a.score==null?'<span class="muted">Awaiting result</span>':`<strong>${fmt(a.score,0)}</strong><div class="tiny">${fmt(a.maxMarks,0)} max</div>`}</td><td>${a.prediction?`${fmt(a.prediction.raw,1)}<div class="tiny">raw estimate</div>`:'—'}</td><td>${a.prediction&&a.score!=null?`<span class="${a.score-a.prediction.raw>=0?'good':'bad'}">${a.score-a.prediction.raw>=0?'+':''}${fmt(a.score-a.prediction.raw,1)}</span>`:'—'}</td><td><div class="table-actions"><button class="btn small" data-action="test-detail" data-id="${esc(a.id)}">View</button><button class="btn small danger" data-action="delete-test" data-id="${esc(a.id)}">×</button></div></td></tr>`).join('')}</tbody></table></div>`:`<div class="card"><div class="empty"><strong>No test attempts in this filter</strong>Log a test or import structured feedback from ChatGPT.</div></div>`}<div class="notice" style="margin-top:15px">To calibrate a forecast, save it before taking the test, then log the actual result with the same test ID (e.g. <b>QPT-4</b>). The app learns from previous residuals but does not claim tiny error tolerances from sparse data.</div>`;
document.getElementById('testFilter').addEventListener('change',e=>{testFilter=e.target.value;renderTests()});}
