function historySum(topic, years){return (years||[]).reduce((sum,y)=>sum+(topic?.years?.[String(y)]?.total||0),0)}
function activeHistoryDataset(){return HISTORICAL_DATASETS[historySubject]||HISTORICAL_DATASETS.Physics}
function historyChapterByNumber(n){const data=activeHistoryDataset();return data.chapters.find(c=>c.chapter_number===Number(n))||data.chapters[0]||null}
function firstMappedHistoryChapter(data){return data?.chapters?.find(c=>['core','support'].includes(c.schedule_mapping_status))||data?.chapters?.[0]||null}
function historyScheduleLabel(c){if(!c.schedule_chapter_id)return 'Historical-only row · not separately listed in QCT catalog';const sc=CHAP_BY_ID[c.schedule_chapter_id];if(!sc)return 'Catalog link unavailable';return `${sc.name} · ${sc.tests} planned QCTs`}
