function renderData(){const root=document.getElementById('view-data');const c=CHAPTERS.length, core=CORE_CHAPTERS.length;root.innerHTML=`<div class="two-col"><div class="card pad"><div class="card-header"><div><h2>Import feedback from ChatGPT</h2><p class="sub">Paste structured JSON. The app validates counts, resolves chapter names and computes every score.</p></div><span class="tag purple">NO API REQUIRED</span></div><label for="jsonImport">JSON payload</label><textarea id="jsonImport" rows="13" spellcheck="false" placeholder='Paste one test object or {"tests":[...]} here. Use the example below.'>${esc(importText)}</textarea><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:11px"><button class="btn primary" id="importJsonBtn">⇄ Validate & import</button><button class="btn" id="loadExampleBtn">Load example schema</button><button class="btn" id="clearJsonBtn">Clear</button></div><div id="importResult" style="margin-top:12px"></div><div class="notice" style="margin-top:14px">Import accepts <code>test_id</code>, <code>date</code>, <code>test_type</code>, <code>correct</code>, <code>wrong</code>, <code>unattempted</code>, <code>total_questions</code>, plus <code>chapter_results</code> and optional <code>question_errors</code>. See schema below.</div></div>
<div class="card pad"><div class="card-header"><div><h2>Backup & restore</h2><p class="sub">Keep your history portable and safe across browser changes.</p></div><span class="tag green">LOCAL FIRST</span></div><div class="chapter-list"><div class="chapter-row"><div><div class="chapter-name">Export all records</div><div class="chapter-meta">Settings, attempts, forecasts, raw chapter outcomes.</div></div><button class="btn small" data-action="export">Export JSON</button></div><div class="chapter-row"><div><div class="chapter-name">Restore backup</div><div class="chapter-meta">Loads a previously exported Loadout JSON backup.</div></div><button class="btn small" data-action="restore-file">Choose file</button></div><div class="chapter-row"><div><div class="chapter-name">Export attempt ledger</div><div class="chapter-meta">CSV for spreadsheets / external analysis.</div></div><button class="btn small" data-action="export-csv">Export CSV</button></div><div class="chapter-row"><div><div class="chapter-name">${window.LoadoutNative?'Offline Android app':'Installable PWA'}</div><div class="chapter-meta">${window.LoadoutNative?'The complete app and historical datasets are bundled in the APK. It runs without a server or internet. Personal records are stored in app-private storage.':'Requires HTTPS hosting or localhost; opening index.html as file will not enable service-worker installation.'}</div></div><span class="tag ${window.LoadoutNative?'green':'amber'}">${window.LoadoutNative?'OFFLINE':'HTTPS'}</span></div></div><input type="file" id="restoreFile" accept="application/json,.json" style="display:none"><div class="notice amber" style="margin-top:15px">${window.LoadoutNative?'Records are stored inside the app’s private internal data. They are removed if you uninstall or clear app data; export a JSON backup every few days and before changing devices.':'Browser storage can be cleared by the operating system or browser. Export a JSON backup every few days and before changing devices.'}</div></div></div>
<div class="card pad" style="margin-bottom:14px"><div class="card-header"><div><h2>Mathematical engine settings</h2><p class="sub">These settings affect future calculations; previous raw outcomes remain unchanged.</p></div><button class="btn" id="saveSettings">Save settings</button></div>
<div class="settings-row"><div><strong>Recency weight α</strong><p>EMA update: newest test gets α weight; older evidence decays exponentially. Start at 0.35 and tune from prediction performance.</p></div><div class="settings-control"><input id="s-alpha" type="number" class="input" min="0.05" max="1" step="0.05" value="${state.settings.alpha}"></div></div>
<div class="settings-row"><div><strong>Prior strength k</strong><p>Equivalent pseudo-test count pulling small-sample chapter estimates toward the cohort mean. Higher values produce more conservative estimates.</p></div><div class="settings-control"><input id="s-prior" type="number" class="input" min="0" max="10" step="0.5" value="${state.settings.priorStrength}"></div></div>
<div class="settings-row"><div><strong>Questions per block test</strong><p>Default QPT/QFT prediction size. The schedule doesn't publish chapter-specific question allocation.</p></div><div class="settings-control"><input id="s-questions" type="number" class="input" min="1" max="200" value="${state.settings.blockQuestions}"></div></div>
<div class="settings-row"><div><strong>Default chapter-test size</strong><p>Initial value for the manual entry form; change per attempt to match actual Quizrr tests.</p></div><div class="settings-control"><input id="s-qctn" type="number" class="input" min="1" max="100" value="${state.settings.defaultQCTQuestions}"></div></div>
<div class="settings-row"><div><strong>Default chapter-test time (min)</strong><p>Initial value only; actual time taken is stored per attempt.</p></div><div class="settings-control"><input id="s-qcttime" type="number" class="input" min="1" max="300" value="${state.settings.defaultQCTMinutes}"></div></div>
<div class="settings-row"><div><strong>Scoring scheme</strong><p>Current model uses +4 for correct, −1 for wrong, 0 for unattempted. A wrong answer loses five marks versus a correct one; an unattempted answer loses four.</p></div><div class="settings-control"><span class="pill">+4 / −1 / 0</span></div></div>
</div>
<div class="two-col"><div class="card pad"><div class="card-header"><div><h2>Data contract for ChatGPT</h2><p class="sub">Tell ChatGPT to output this structure after each test.</p></div><button class="btn small" id="copySchema">Copy schema</button></div><pre id="schemaCode" style="white-space:pre-wrap;overflow-wrap:anywhere;background:#080e19;border:1px solid var(--border);padding:14px;border-radius:12px;color:#cbd6ed;font-size:10px;line-height:1.65">${esc(JSON.stringify({test_id:'REPLACE-WITH-REAL-TEST-ID',date:'2026-10-22',test_type:'QCT',title:'REPLACE WITH REAL TEST NAME',total_questions:15,duration_min:30,correct:10,wrong:2,unattempted:3,chapter_results:[{chapter:'Motion In One Dimension',total_questions:15,correct:10,wrong:2,unattempted:3,error_counts:{conceptual:0,recall:1,application:1,comparison:0,calculation:0,careless:0,time:0,unclassified:0},notes:'Add only evidence-supported diagnosis.'}],question_errors:[{chapter:'Motion In One Dimension',topic:'Relative motion',outcome:'wrong',category:'application',time_seconds:90,notes:'Optional concise post-mortem.'}]},null,2))}</pre><div class="notice" style="margin-top:12px">If only total score counts are known, import them. If chapter allocations or mistake categories aren't in the source, leave them out rather than asking ChatGPT to guess. App score = 4C − W.</div></div>
<div class="card pad"><div class="card-header"><div><h2>Schedule integrity</h2><p class="sub">Transcribed from the uploaded October Batch schedule PDF.</p></div><span class="tag">SOURCE MAP</span></div><div class="grid stats" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="stat-card"><div class="stat-label">QCT rows</div><div class="stat-value">${c}</div><div class="stat-foot">Planned tests total 471</div></div><div class="stat-card"><div class="stat-label">Core-filter rows</div><div class="stat-value">${core}</div><div class="stat-foot">Asterisk extras + support topic separated</div></div><div class="stat-card"><div class="stat-label">Part tests</div><div class="stat-value">16</div><div class="stat-foot">12 topic blocks + 4 checkpoints</div></div><div class="stat-card"><div class="stat-label">Full tests</div><div class="stat-value">30</div><div class="stat-foot">First upload 29 Nov 2026</div></div></div><div class="divider"></div><p class="sub">Chapter QCT planned counts from the schedule are retained as metadata, not treated as completed attempts. QPT chapter lists and QFT upload dates are preloaded. The schedule's footnote says dates may change.</p></div></div>
<div class="card pad" style="margin-bottom:14px"><div class="card-header"><div><h2>Mathematical reference</h2><p class="sub">The calculator is deterministic: the same records and settings yield the same answer.</p></div><span class="tag purple">FORMULAS</span></div><div class="chapter-list"><div class="chapter-row"><div><div class="chapter-name">Net marks</div><div class="chapter-meta">S = 4C − W; U has zero marks. Maximum = 4N.</div></div><div class="chapter-score"><strong>4C − W</strong><small>per test</small></div></div><div class="chapter-row"><div><div class="chapter-name">Scaled net score</div><div class="chapter-meta">P = 100S/(4N). It is a normalized test result, not literal concept mastery.</div></div><div class="chapter-score"><strong>0–100*</strong><small>can be negative</small></div></div><div class="chapter-row"><div><div class="chapter-name">Recency weighting</div><div class="chapter-meta">EMAₜ = αPₜ + (1−α)EMAₜ₋₁.</div></div><div class="chapter-score"><strong>α=${fmt(state.settings.alpha,2)}</strong><small>latest test weight</small></div></div><div class="chapter-row"><div><div class="chapter-name">Small-sample shrinkage</div><div class="chapter-meta">M = (m·EMA + k·μ)/(m+k), where μ is the overall core chapter-test baseline.</div></div><div class="chapter-score"><strong>k=${fmt(state.settings.priorStrength,1)}</strong><small>prior strength</small></div></div><div class="chapter-row"><div><div class="chapter-name">Raw block forecast</div><div class="chapter-meta">Ŝ = Nblock × mean(4Mⱼ/100) across chapters in the scheduled syllabus. Equal chapter weighting is an explicit fallback.</div></div><div class="chapter-score"><strong>N=${state.settings.blockQuestions}</strong><small>block questions</small></div></div><div class="chapter-row"><div><div class="chapter-name">Calibration + residual</div><div class="chapter-meta">Residual = actual − saved raw forecast. Bias correction / linear regression use only prior saved forecasts for the same test family.</div></div><div class="chapter-score"><strong>a + bŜ</strong><small>learned correction</small></div></div></div><div class="notice amber" style="margin-top:13px">Prediction decimals describe arithmetic precision, not guaranteed accuracy. Intervals remain provisional until enough comparable forecasts have been saved before tests and then graded.</div></div>
<div class="card pad"><div class="card-header"><div><h2>Danger zone</h2><p class="sub">This affects local records in this browser only.</p></div></div><div class="settings-row"><div><strong>Delete all records</strong><p>Clears all attempts, forecasts, and custom settings. Export a backup first; this cannot be undone.</p></div><button class="btn danger" id="resetAll">Reset data</button></div></div>`;
document.getElementById('jsonImport').addEventListener('input',e=>{importText=e.target.value});document.getElementById('importJsonBtn').addEventListener('click',()=>importJSON(document.getElementById('jsonImport').value));document.getElementById('loadExampleBtn').addEventListener('click',()=>{document.getElementById('jsonImport').value=JSON.stringify({test_id:'REPLACE-WITH-REAL-TEST-ID',date:dateTimeISO(),test_type:'QCT',title:'REPLACE WITH REAL TEST NAME',total_questions:15,duration_min:30,correct:10,wrong:2,unattempted:3,chapter_results:[{chapter:'Motion In One Dimension',total_questions:15,correct:10,wrong:2,unattempted:3,error_counts:{application:1,careless:1}}]},null,2);toast('Example schema loaded. Replace the values with real results before importing.');});document.getElementById('clearJsonBtn').addEventListener('click',()=>{document.getElementById('jsonImport').value='';document.getElementById('importResult').innerHTML='';});document.getElementById('saveSettings').addEventListener('click',saveSettings);document.getElementById('copySchema').addEventListener('click',()=>copyText(document.getElementById('schemaCode').textContent));document.getElementById('resetAll').addEventListener('click',resetAll);restoreFileHandler();}
function openTestModal(schedule=null){const modal=document.getElementById('testModal');document.getElementById('formError').style.display='none';document.getElementById('f-date').value=dateTimeISO();document.getElementById('f-type').value=schedule?(schedule.id.startsWith('QPT')?'QPT':'QFT'):'QCT';document.getElementById('f-id').value=schedule?schedule.id:'';document.getElementById('f-title').value=schedule?schedule.name:'';document.getElementById('f-chapter').value='';document.getElementById('f-n').value=schedule?state.settings.blockQuestions:state.settings.defaultQCTQuestions;document.getElementById('f-correct').value=0;document.getElementById('f-wrong').value=0;document.getElementById('f-unattempted').value=document.getElementById('f-n').value;document.getElementById('f-minutes').value=schedule?state.settings.blockMinutes:state.settings.defaultQCTMinutes;document.getElementById('f-subject').value='';document.getElementById('f-notes').value='';modal.classList.add('open');setTimeout(()=>document.getElementById('f-title').focus(),20)}
function closeModal(){document.getElementById('testModal').classList.remove('open')}
function initModal(){const sel=document.getElementById('f-chapter');sel.innerHTML='<option value="">Select a chapter…</option>'+CHAPTERS.map(c=>`<option value="${c.id}">${esc(c.subject)} · ${esc(c.name)}${c.status==='extra'?' *':c.status==='support'?' · support':''}</option>`).join('');document.getElementById('closeModal').addEventListener('click',closeModal);document.getElementById('cancelModal').addEventListener('click',closeModal);document.getElementById('testModal').addEventListener('click',e=>{if(e.target.id==='testModal')closeModal()});document.getElementById('f-type').addEventListener('change',e=>{const n=document.getElementById('f-n');if(e.target.value==='QPT'||e.target.value==='QFT'){if(Number(n.value)===Number(state.settings.defaultQCTQuestions))n.value=state.settings.blockQuestions;document.getElementById('f-minutes').value=state.settings.blockMinutes;}else{n.value=state.settings.defaultQCTQuestions;document.getElementById('f-minutes').value=state.settings.defaultQCTMinutes;}syncUnattempted()});['f-n','f-correct','f-wrong'].forEach(id=>document.getElementById(id).addEventListener('input',syncUnattempted));document.getElementById('testForm').addEventListener('submit',saveManualTest);document.getElementById('closeDetail').addEventListener('click',()=>document.getElementById('detailModal').classList.remove('open'));document.getElementById('detailModal').addEventListener('click',e=>{if(e.target.id==='detailModal')e.currentTarget.classList.remove('open')});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.getElementById('detailModal').classList.remove('open')}})}
function syncUnattempted(){const n=Number(document.getElementById('f-n').value)||0,c=Number(document.getElementById('f-correct').value)||0,w=Number(document.getElementById('f-wrong').value)||0;document.getElementById('f-unattempted').value=Math.max(0,n-c-w)}
function saveManualTest(e){e.preventDefault();const v=id=>document.getElementById(id).value;const type=v('f-type'),testId=v('f-id').trim()||`${type}-${Date.now()}`,date=v('f-date'),title=v('f-title').trim(),n=Number(v('f-n')),correct=Number(v('f-correct')),wrong=Number(v('f-wrong')),unattempted=Number(v('f-unattempted')),minutes=Number(v('f-minutes')||0),cid=v('f-chapter');const error=document.getElementById('formError');if(!Number.isInteger(n)||n<1||![correct,wrong,unattempted].every(x=>Number.isInteger(x)&&x>=0)||correct+wrong+unattempted!==n){error.style.display='block';error.textContent=`Invalid counts: C + W + U must equal N. Currently ${correct} + ${wrong} + ${unattempted} = ${correct+wrong+unattempted}, N = ${n}.`;return;}if(state.attempts.some(a=>String(a.testId).toUpperCase()===testId.toUpperCase()&&a.score!=null)){error.style.display='block';error.textContent='A completed attempt with this test ID already exists. Use a unique attempt ID, e.g. append -2.';return;}const ch=cid?CHAP_BY_ID[cid]:null;if(type==='QCT'&&!ch){error.style.display='block';error.textContent='Choose the chapter for a chapter-wise test, so the result updates the right chapter.';return;}const f=linkedForecast(testId,type);const attempt={id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),testId,date,type,title,n,correct,wrong,unattempted,minutes,score:scoreOf(correct,wrong),maxMarks:n*state.settings.correctMarks,subject:ch?ch.subject:(v('f-subject')||null),notes:v('f-notes').trim(),chapterResults:ch?[{chapterId:ch.id,n,correct,wrong,unattempted,errorCounts:{},questionErrors:[]}]:[],prediction:f?{...f,attachedAt:new Date().toISOString()}:null,createdAt:new Date().toISOString()};state.attempts.push(attempt);persist();closeModal();renderCurrent();toast(f?'Result saved and prior forecast linked.':'Test result saved. Add chapter outcomes through JSON import for mixed tests.');}
function makeChapterResult(raw,defaultSubject){const name=raw.chapter??raw.chapter_name??raw.name??raw.chapterId??raw.chapter_id;const ch=CHAP_BY_ID[name]||resolveChapter(name,raw.subject||defaultSubject);if(!ch) return {error:`Could not resolve chapter “${name||'(missing)'}”. Use the exact schedule name or its ID.`};const n=Number(raw.total_questions??raw.n??raw.questions??((Number(raw.correct)||0)+(Number(raw.wrong)||0)+(Number(raw.unattempted)||0)));const c=Number(raw.correct??raw.C??0),w=Number(raw.wrong??raw.W??0),u=Number(raw.unattempted??raw.skipped??raw.U??Math.max(0,n-c-w));if(!Number.isInteger(n)||n<1||![c,w,u].every(x=>Number.isInteger(x)&&x>=0)||c+w+u!==n)return {error:`Invalid counts for ${ch.name}: C + W + U must equal N.`};const errorCounts={};const source=raw.error_counts||raw.errorCounts||raw.errors||{};Object.entries(source).forEach(([k,v])=>{const kk=mapTag(k);if(kk)errorCounts[kk]=(errorCounts[kk]||0)+(Number(v)||0)});const questionErrors=(raw.question_errors||raw.questionErrors||[]).map(normalizeQuestionError).filter(Boolean);if(Array.isArray(raw.error_categories))raw.error_categories.forEach(tag=>{const k=mapTag(tag);if(k)errorCounts[k]=(errorCounts[k]||0)+1});return {chapterId:ch.id,n,correct:c,wrong:w,unattempted:u,errorCounts,questionErrors,notes:raw.notes||'',topics:raw.topics||raw.topic||null};}
function mapTag(value){const n=norm(value);const lookup={conceptual:'conceptual','conceptual model':'conceptual',recall:'recall','memory / recall':'recall','application':'application','application mechanism':'application','mechanism':'application','comparison':'comparison','comparison order':'comparison','ordering':'comparison','calculation':'calculation','arithmetic':'calculation','careless':'careless','careless reading':'careless','reading':'careless','time':'time','time selection':'time','time management':'time','unclassified':'unclassified','unknown':'unclassified'};return lookup[n]||null}
function normalizeQuestionError(raw){if(!raw||typeof raw!=='object')return null;const ch=resolveChapter(raw.chapter||raw.chapter_name,raw.subject);const outcome=norm(raw.outcome||raw.status);const cat=mapTag(raw.category||raw.error_category||raw.reason)||'unclassified';return {chapterId:ch?ch.id:null,topic:raw.topic||null,outcome:['wrong','incorrect','error'].includes(outcome)?'wrong':['unattempted','skipped','not attempted'].includes(outcome)?'unattempted':outcome||'unknown',category:cat,timeSeconds:Number(raw.time_seconds??raw.timeSeconds)||null,notes:raw.notes||''}}
function normalizeSubjectResults(raw){if(!Array.isArray(raw))return [];const out=[];raw.forEach(x=>{if(!x||typeof x!=='object')return;const subject=SUBJECTS.find(s=>s.toLowerCase()===String(x.subject||x.name||'').toLowerCase());if(!subject)return;const n=Number(x.total_questions??x.n??x.questions??0);const c=Number(x.correct??x.C??0),w=Number(x.wrong??x.W??0),u=Number(x.unattempted??x.skipped??x.U??Math.max(0,n-c-w));if(Number.isInteger(n)&&n>0&&[c,w,u].every(v=>Number.isInteger(v)&&v>=0)&&c+w+u===n)out.push({subject,n,correct:c,wrong:w,unattempted:u,score:scoreOf(c,w),maxMarks:n*state.settings.correctMarks});});return out;}
function normalizeTest(raw,force=false){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw new Error('Each test must be a JSON object.');const testId=String(raw.test_id??raw.testId??raw.id??'').trim();if(!testId)throw new Error('Each test needs a unique test_id.');if(/^(REPLACE|EXAMPLE|PLACEHOLDER)/i.test(testId))throw new Error('Replace the placeholder test_id with the real test ID before importing. Example data is never stored as a real result.');const date=String(raw.date??raw.attempt_date??dateTimeISO()).slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(date))throw new Error(`Invalid date for ${testId}. Use YYYY-MM-DD.`);let type=String(raw.test_type??raw.type??'OTHER').toUpperCase();if(type==='CHAPTERWISE'||type==='CHAPTER')type='QCT';if(type==='PART'||type==='PART TEST')type='QPT';if(type==='FULL'||type==='FULL TEST')type='QFT';if(!['QCT','QPT','QFT','HFT','OTHER'].includes(type))type='OTHER';const correct=Number(raw.correct??raw.C??0),wrong=Number(raw.wrong??raw.W??0),n=Number(raw.total_questions??raw.n??raw.questions??((Number(raw.correct)||0)+(Number(raw.wrong)||0)+(Number(raw.unattempted)||0))),unattempted=Number(raw.unattempted??raw.skipped??raw.U??Math.max(0,n-correct-wrong));if(!Number.isInteger(n)||n<1||!Number.isInteger(correct)||!Number.isInteger(wrong)||!Number.isInteger(unattempted)||[correct,wrong,unattempted].some(x=>x<0)||correct+wrong+unattempted!==n)throw new Error(`Invalid C/W/U counts for ${testId}. Require C + W + U = total_questions.`);const subject=raw.subject&&SUBJECTS.some(s=>s.toLowerCase()===String(raw.subject).toLowerCase())?SUBJECTS.find(s=>s.toLowerCase()===String(raw.subject).toLowerCase()):null;let chapterResults=[];for(const r of (raw.chapter_results||raw.chapterResults||[])){const x=makeChapterResult(r,subject);if(x.error)throw new Error(`${testId}: ${x.error}`);chapterResults.push(x);}const topChapter=raw.chapter_id||raw.chapterId||raw.chapter||raw.chapter_name;if(topChapter&&!chapterResults.length){const x=makeChapterResult({chapter:topChapter,total_questions:n,correct,wrong,unattempted,error_counts:raw.error_counts||raw.errorCounts,question_errors:raw.question_errors||raw.questionErrors,notes:raw.notes},subject);if(x.error)throw new Error(`${testId}: ${x.error}`);chapterResults.push(x);}const errors=(raw.question_errors||raw.questionErrors||[]).map(normalizeQuestionError).filter(Boolean);errors.forEach(err=>{if(err.chapterId){const target=chapterResults.find(r=>r.chapterId===err.chapterId);if(target){target.questionErrors=target.questionErrors||[];target.questionErrors.push(err);}}});const subjectResults=normalizeSubjectResults(raw.subject_results||raw.subjectResults||[]);return {id:String(raw.record_id||raw.recordId||testId),testId,date,type,title:String(raw.title??raw.name??testId),n,correct,wrong,unattempted,minutes:Number(raw.duration_min??raw.minutes??raw.time_taken_min)||null,score:scoreOf(correct,wrong),maxMarks:n*state.settings.correctMarks,subject,notes:String(raw.notes||''),chapterResults,questionErrors:errors,subjectResults,prediction:null,createdAt:new Date().toISOString()};}
function importJSON(text){const result=document.getElementById('importResult');try{const parsed=JSON.parse(text);const rows=Array.isArray(parsed)?parsed:(Array.isArray(parsed.tests)?parsed.tests:[parsed]);if(!rows.length)throw new Error('No test objects found.');const normalized=rows.map(x=>normalizeTest(x));const seen=new Set(state.attempts.filter(a=>a.score!=null).map(a=>String(a.testId).toUpperCase()));const dup=normalized.filter(a=>seen.has(a.testId.toUpperCase()));const batchIds=normalized.map(a=>a.testId.toUpperCase());const repeated=batchIds.filter((id,i)=>batchIds.indexOf(id)!==i);if(dup.length||repeated.length)throw new Error(`Duplicate test_id(s) detected: ${[...new Set([...dup.map(a=>a.testId),...repeated])].join(', ')}. Use unique attempt IDs or remove duplicates from the import.`);normalized.forEach(a=>{const f=linkedForecast(a.testId,a.type);if(f)a.prediction={...f,attachedAt:new Date().toISOString()};});state.attempts.push(...normalized);persist();importText=text;result.innerHTML=`<div class="notice green"><b>Imported ${normalized.length} test${normalized.length===1?'':'s'} successfully.</b><br>Saved ${normalized.reduce((s,a)=>s+a.chapterResults.length,0)} chapter-level result row(s). Total scores calculated by Loadout. ${normalized.reduce((s,a)=>s+(a.chapterResults.some(r=>r.errorCounts&&Object.keys(r.errorCounts).length)?1:0),0)} or more diagnostic records may include error tags; unprovided diagnoses remain unknown.</div>`;toast(`Imported ${normalized.length} test record(s).`);renderDashboard();}catch(e){result.innerHTML=`<div class="notice red"><b>Import rejected — no records were added.</b><br>${esc(e.message||String(e))}</div>`;}}
function saveSettings(){const alpha=Number(document.getElementById('s-alpha').value),prior=Number(document.getElementById('s-prior').value),qn=Number(document.getElementById('s-questions').value),qctn=Number(document.getElementById('s-qctn').value),qcttime=Number(document.getElementById('s-qcttime').value);if(!(alpha>=.05&&alpha<=1)||!(prior>=0&&prior<=10)||!(Number.isInteger(qn)&&qn>=1&&qn<=200)||!(Number.isInteger(qctn)&&qctn>=1&&qctn<=100)||!(Number.isFinite(qcttime)&&qcttime>0&&qcttime<=300)){toast('One or more settings are outside the allowed range.');return;}state.settings.alpha=alpha;state.settings.priorStrength=prior;state.settings.blockQuestions=qn;state.settings.defaultQCTQuestions=qctn;state.settings.defaultQCTMinutes=qcttime;persist();renderData();toast('Settings saved. All derived estimates now use the new settings.');}
function saveForecast(id){const type=id.startsWith('QPT')?'QPT':'QFT';const p=predict(type,id);if(!p)return;const existing=state.forecasts.findIndex(f=>f.testId===id&&f.type===type);const forecast={id:`forecast-${id}`,testId:id,type,date:p.sched.date,title:p.sched.name,savedOn:dateTimeISO(),raw:p.raw,calibrated:p.calibrated,lower:p.lower,upper:p.upper,half:p.half,confidence:p.confidence,covered:p.covered,totalChapters:p.chapters.length,chapterIds:p.chapters.map(x=>x.chapter.id),questionCount:p.questionCount,calibration:{n:p.calibration.n,method:p.calibration.method},assumptions:'Equal chapter weight for QPT; core-chapter average for QFT. QCT records update chapter mastery.'};if(existing>=0)state.forecasts[existing]=forecast;else state.forecasts.push(forecast);persist();renderForecasts();toast('Forecast snapshot saved. Log the result under the same ID to grade it.');}
function exportJSON(){const out={app:'Loadout — JEE Performance Engine',schemaVersion:1,exportedAt:new Date().toISOString(),sourceSchedule:'Most Relevant JEE Main 2027 Test Series — October Batch (Droppers)',settings:state.settings,attempts:state.attempts,forecasts:state.forecasts};downloadBlob(JSON.stringify(out,null,2),`loadout-jee-2027-backup-${dateTimeISO()}.json`,'application/json');toast('Backup exported. Store it somewhere safe.');}
function downloadBlob(content,name,type){if(window.LoadoutNative&&typeof window.LoadoutNative.saveFileBase64==='function'){try{const bytes=new TextEncoder().encode(String(content));let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));const ok=window.LoadoutNative.saveFileBase64(name,type,btoa(binary));if(ok){toast(`Saved ${name} to Downloads/Loadout.`);return;}toast('Android could not save the file. Try exporting again or use the browser version.');return;}catch(err){console.error('Native export failed',err);toast('Native export failed.');return;}}const b=new Blob([content],{type});const url=URL.createObjectURL(b);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCSV(){const cols=['test_id','date','type','title','total_questions','correct','wrong','unattempted','score','max_marks','minutes','subject','predicted_raw','prediction_residual','chapter_results'];const rows=[cols,...state.attempts.map(a=>[a.testId,a.date,a.type,a.title,a.n,a.correct,a.wrong,a.unattempted,a.score,a.maxMarks,a.minutes,a.subject||'',a.prediction?.raw??'',a.score!=null&&a.prediction?a.score-a.prediction.raw:'',(a.chapterResults||[]).map(r=>`${CHAP_BY_ID[r.chapterId]?.name||r.chapterId}:${r.correct}/${r.wrong}/${r.unattempted}`).join(';')])];const csv=rows.map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');downloadBlob('\ufeff'+csv,`loadout-jee-2027-ledger-${dateTimeISO()}.csv`,'text/csv;charset=utf-8');toast('CSV exported.');}
function restoreFile(){document.getElementById('restoreFile').click();}
function restoreFileHandler(){const fileInput=document.getElementById('restoreFile');if(!fileInput)return;fileInput.addEventListener('change',async e=>{const f=e.target.files&&e.target.files[0];if(!f)return;try{const d=JSON.parse(await f.text());if(!Array.isArray(d.attempts)||!d.settings)throw new Error('Not a Loadout backup.');if(!confirm(`Replace current data with backup? ${d.attempts.length} attempts.`))return;state={...structuredClone(DEFAULTS),...d,settings:{...DEFAULTS.settings,...d.settings},attempts:d.attempts,forecasts:d.forecasts||[]};persist();renderCurrent();toast('Backup restored.');}catch(err){toast('Restore failed: '+err.message)}finally{e.target.value='';}})}
function resetAll(){if(!confirm('Delete ALL test history, forecasts, and settings stored by Loadout in this browser? Export a backup first.'))return;if(!confirm('Final confirmation: this cannot be undone. Continue?'))return;state=structuredClone(DEFAULTS);persist();renderCurrent();toast('Local records reset.');}
function copyText(text){if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(text).then(()=>toast('Copied to clipboard.')).catch(()=>fallbackCopy(text));else fallbackCopy(text)}function fallbackCopy(text){const t=document.createElement('textarea');t.value=text;document.body.appendChild(t);t.select();try{document.execCommand('copy');toast('Copied.')}catch(e){toast('Copy failed; select and copy manually.')}t.remove()}
function openChapterDetail(id){const c=CHAP_BY_ID[id];if(!c)return;const s=chapterStats(c);document.getElementById('detailTitle').textContent=c.name;document.getElementById('detailSubtitle').textContent=`${c.subject} · ${c.tests} planned QCTs · ${c.status==='extra'?'Beyond JEE Main (starred in source)':c.status==='support'?'Support topic':'Core catalog row'}`;const errorHtml=TAGS.map(t=>`<div class="bar-row"><div class="bar-name">${TAG_LABELS[t]}</div><div class="progress"><span style="width:${Math.min(100,(s.errorMap[t]||0)*20)}%;background:${(s.errorMap[t]||0)?'var(--amber)':'#526078'}"></span></div><div class="bar-value">${s.errorMap[t]||0}</div></div>`).join('');document.getElementById('detailBody').innerHTML=`<div class="grid stats" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="stat-card card"><div class="stat-label">Mastery index</div><div class="stat-value">${s.mastery==null?'—':fmt(s.mastery,1)}</div><div class="stat-foot">${s.confidence} evidence</div></div><div class="stat-card card"><div class="stat-label">Completed QCTs</div><div class="stat-value">${s.count}<span class="muted" style="font-size:13px"> / ${c.tests}</span></div><div class="stat-foot">${s.transferCount} mixed-test observations, separately weighted</div></div><div class="stat-card card"><div class="stat-label">Raw mean</div><div class="stat-value">${s.rawAvg==null?'—':fmt(s.rawAvg,1)}</div><div class="stat-foot">Scaled net marks per test</div></div><div class="stat-card card"><div class="stat-label">Consistency σ</div><div class="stat-value">${s.sd==null?'—':fmt(s.sd,1)}</div><div class="stat-foot">Sample standard deviation in pp</div></div></div><div class="card pad" style="margin-top:13px"><div class="card-header"><div><h2>Last attempts</h2><p class="sub">Chronological result history for this chapter</p></div><button class="btn small" data-action="log-chapter" data-id="${c.id}">＋ Log QCT</button></div>${s.attempts.length?`<div class="table-wrap"><table><thead><tr><th>Test / date</th><th>C/W/U</th><th>Score</th><th>Scaled</th><th>Time</th></tr></thead><tbody>${s.attempts.slice().reverse().map(a=>`<tr><td>${esc(a.title||a.testId)}<div class="tiny">${dateFmt(a.date)}</div></td><td>${a.correct}/${a.wrong}/${a.unattempted}</td><td>${scoreOf(a.correct,a.wrong)} / ${a.n*state.settings.correctMarks}</td><td>${fmt(a.scaled,1)}</td><td>${a.minutes??'—'} min</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>No attempts logged</strong>Log a QCT or import a chapter-level result.</div>`}</div><div class="card pad" style="margin-top:13px"><div class="card-header"><div><h2>Error profile</h2><p class="sub">Only explicit imported classifications count as classified errors.</p></div></div><div class="bar-list">${errorHtml}</div><div class="divider"></div><div class="notice">Estimated uncorrected loss: <b>${s.count?fmt(s.lost,0):'—'} marks</b> across recorded attempts, where wrong answers cost 5 marks relative to correct and unattempted questions cost 4. This is historical opportunity cost, not a guaranteed recoverable amount.</div></div>`;document.getElementById('detailModal').classList.add('open')}
function openTestDetail(id){const a=state.attempts.find(x=>x.id===id);if(!a)return;document.getElementById('detailTitle').textContent=a.title||a.testId;document.getElementById('detailSubtitle').textContent=`${a.testId} · ${a.type} · ${dateFmt(a.date)}`;document.getElementById('detailBody').innerHTML=`<div class="grid stats" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="stat-card card"><div class="stat-label">Net score</div><div class="stat-value">${a.score==null?'Pending':fmt(a.score,0)}</div><div class="stat-foot">${a.score==null?'Forecast only':`${a.maxMarks} max marks`}</div></div><div class="stat-card card"><div class="stat-label">Correct / wrong / unattempted</div><div class="stat-value">${a.score==null?'—':`${a.correct}/${a.wrong}/${a.unattempted}`}</div><div class="stat-foot">${a.n} total questions · ${a.minutes??'—'} min</div></div></div><div class="card pad" style="margin-top:13px"><h2>Prediction record</h2>${a.prediction?`<div class="forecast-scale"><div class="scale-item"><small>RAW PREDICTION</small><strong>${fmt(a.prediction.raw,1)}</strong></div><div class="scale-item"><small>ACTUAL</small><strong>${a.score==null?'Pending':fmt(a.score,0)}</strong></div><div class="scale-item"><small>RESIDUAL</small><strong>${a.score==null?'—':fmt(a.score-a.prediction.raw,1)}</strong></div></div>`:`<p class="sub" style="margin-top:10px">No pre-test forecast attached. This result updates chapter estimates only, if chapter-level rows are available.</p>`}</div>${a.score!=null?`<div class="notice amber" style="margin-top:13px"><b>Theoretical score ceiling: ${fmt(Math.min(a.maxMarks,a.score+5*a.wrong+4*a.unattempted),0)} / ${a.maxMarks}</b> if every wrong and unattempted question had instead become correct. This is an opportunity-cost ceiling, not a realistic forecast of recoverable marks.</div>`:''}<div class="card pad" style="margin-top:13px"><div class="card-header"><div><h2>Chapter-level data</h2><p class="sub">Imported data supplied to the mathematical engine</p></div></div>${a.chapterResults?.length?`<div class="table-wrap"><table><thead><tr><th>Chapter</th><th>C/W/U</th><th>Score</th><th>Scaled</th><th>Error tags</th></tr></thead><tbody>${a.chapterResults.map(r=>`<tr><td>${esc(CHAP_BY_ID[r.chapterId]?.name||r.chapterId)}</td><td>${r.correct}/${r.wrong}/${r.unattempted}</td><td>${scoreOf(r.correct,r.wrong)}/${r.n*state.settings.correctMarks}</td><td>${fmt(scorePercent(scoreOf(r.correct,r.wrong),r.n),1)}</td><td>${Object.entries(r.errorCounts||{}).filter(([,n])=>n).map(([tag,n])=>`${esc(TAG_LABELS[tag]||tag)}: ${n}`).join('<br>')||'Not classified'}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>No chapter-level breakdown attached</strong>For a mixed test, re-import with chapter_results if you know the actual chapter allocation. Avoid guessing it.</div>`}</div>${a.subjectResults&&a.subjectResults.length?`<div class="card pad" style="margin-top:13px"><h2>Subject split</h2><div class="forecast-scale">${a.subjectResults.map(sr=>`<div class="scale-item"><small>${esc(sr.subject.toUpperCase())}</small><strong>${fmt(sr.score,0)} / ${sr.maxMarks}</strong><small>${sr.correct}C · ${sr.wrong}W · ${sr.unattempted}U</small></div>`).join('')}</div></div>`:''}${a.notes?`<div class="notice" style="margin-top:13px">${esc(a.notes)}</div>`:''}<div class="modal-footer"><button class="btn danger" data-action="delete-test" data-id="${a.id}">Delete record</button><button class="btn" id="detailDone">Close</button></div>`;document.getElementById('detailModal').classList.add('open');const d=document.getElementById('detailDone');if(d)d.addEventListener('click',()=>document.getElementById('detailModal').classList.remove('open'))}
function deleteTest(id){const a=state.attempts.find(x=>x.id===id);if(!a)return;if(!confirm(`Delete test record “${a.title||a.testId}”? This also removes its contribution to historical estimates.`))return;state.attempts=state.attempts.filter(x=>x.id!==id);persist();document.getElementById('detailModal').classList.remove('open');renderCurrent();toast('Test record deleted.');}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;if(action==='log')openTestModal();else if(action==='import')switchView('data');else if(action==='forecast')switchView('forecasts');else if(action==='tests')switchView('tests');else if(action==='chapters')switchView('chapters');else if(action==='forecast-schedule'){forecastType=id.startsWith('QPT')?'QPT':'QFT';forecastId=id;switchView('forecasts');}else if(action==='save-forecast')saveForecast(id);else if(action==='log-schedule'){const s=getSchedule(id.startsWith('QPT')?'QPT':'QFT',id);openTestModal(s);}else if(action==='chapter-detail')openChapterDetail(id);else if(action==='log-chapter'){const c=CHAP_BY_ID[id];document.getElementById('detailModal').classList.remove('open');openTestModal();document.getElementById('f-chapter').value=id;document.getElementById('f-type').value='QCT';document.getElementById('f-title').value=`${c.name} — Test ${chapterStats(c).count+1}`;document.getElementById('f-n').value=state.settings.defaultQCTQuestions;document.getElementById('f-unattempted').value=state.settings.defaultQCTQuestions;}else if(action==='test-detail')openTestDetail(id);else if(action==='delete-test')deleteTest(id);else if(action==='history-topic'){const c=historyChapterByNumber(historyChapterNumber);const topic=c?.topics?.[Number(el.dataset.index)];if(topic){historyTopicName=topic.name;renderHistorical();}}else if(action==='history-chapter'){historyChapterNumber=Number(id);historyTopicName='';switchView('historical');}else if(action==='export')exportJSON();else if(action==='export-csv')exportCSV();else if(action==='restore-file')restoreFile();});
window.loadoutHandleNativeBack=function(){const modal=document.getElementById('detailModal');if(modal&&modal.classList.contains('open')){modal.classList.remove('open');return true;}if(currentView!=='dashboard'){switchView('dashboard');return true;}return false;};
function init(){if(window.LoadoutNative){document.documentElement.classList.add('native-app');const b=document.getElementById('installApp');if(b)b.style.display='none';}navWiring();initModal();document.getElementById('f-type').dispatchEvent(new Event('change'));renderCurrent();const installBtn=document.getElementById('installApp');if(installBtn)installBtn.addEventListener('click',async()=>{if(!installPromptEvent){toast('To install, open the hosted HTTPS page in your browser menu and choose Install app / Add to Home screen.');return;}installPromptEvent.prompt();const choice=await installPromptEvent.userChoice;installPromptEvent=null;installBtn.style.display='none';if(choice&&choice.outcome==='accepted')toast('Installation started.');});if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').then(()=>{}).catch(e=>console.warn('Service worker unavailable',e));}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPromptEvent=event;const button=document.getElementById('installApp');if(button)button.style.display='inline-flex';});window.addEventListener('appinstalled',()=>{const button=document.getElementById('installApp');if(button)button.style.display='none';installPromptEvent=null;});
init();

/* ========== AI Coach / Multi-provider Chat ========== */
const CHAT_STORAGE_KEY = 'loadout_chat_v2';
const LEGACY_CHAT_STORAGE_KEY = 'loadout_chat_v1';
const DEFAULT_SYSTEM = `You are Loadout AI Coach, an expert JEE Advanced / JEE Main mentor for the 2027 cycle.
You help students with:
- Concept explanations (Physics, Chemistry, Mathematics) at JEE depth
- Weak-chapter prioritization and revision strategy
- Test analysis, error patterns, time management
- PYQ trends and high-yield topics (you know the 2019–2025 landscape)
- Mental models, mnemonic hooks, and deliberate practice plans

Be precise, structured, and encouraging but realistic. Prefer short paragraphs, bullet lists, and numbered steps.
When useful, reference chapter-level mastery thinking (not raw data you cannot see). Never invent specific past-paper statistics; speak in general terms unless the user provides numbers.
If the user pastes a question, solve it step-by-step with JEE-appropriate rigor.
Keep answers focused; ask clarifying questions only when necessary.`;

// Provider defaults are presets, not promises of unlimited free usage.
const CHAT_PROVIDERS = {
  gemini: {
    name: 'Google Gemini · Free tier', kind: 'gemini',
    baseUrl: 'https://generativelanguage.googleapis.com/v1beta',
    model: 'gemini-3.8-flash', keyUrl: 'https://aistudio.google.com/apikey',
    note: 'Free token access is available for selected models. Quotas vary by model and Google project.'
  },
  groq: {
    name: 'Groq · Free tier', kind: 'openai',
    baseUrl: 'https://api.groq.com/openai/v1',
    model: 'openai/gpt-oss-20b', keyUrl: 'https://console.groq.com/keys',
    note: 'Fast inference with model-specific request and token limits. Check your Groq Limits page.'
  },
  openrouter: {
    name: 'OpenRouter · Free models', kind: 'openai',
    baseUrl: 'https://openrouter.ai/api/v1',
    model: 'openrouter/free', keyUrl: 'https://openrouter.ai/keys',
    note: 'Use openrouter/free or a model ID ending in :free. Free-model capacity and daily limits can change.'
  },
  huggingface: {
    name: 'Hugging Face · Included credits', kind: 'openai',
    baseUrl: 'https://router.huggingface.co/v1',
    model: 'deepseek-ai/DeepSeek-R1:fastest', keyUrl: 'https://huggingface.co/settings/tokens',
    note: 'Free accounts currently receive a small monthly Inference Providers credit; this is not unlimited free inference.'
  },
  cerebras: {
    name: 'Cerebras · Trial credit', kind: 'openai',
    baseUrl: 'https://api.cerebras.ai/v1',
    model: 'gpt-oss-120b', keyUrl: 'https://cloud.cerebras.ai/',
    note: 'Cerebras currently advertises a one-time $5 trial credit after adding a valid payment method. It is not recurring free usage.'
  },
  custom: {
    name: 'Custom OpenAI-compatible API', kind: 'openai',
    baseUrl: 'https://api.openai.com/v1',
    model: 'gpt-4o-mini', keyUrl: '',
    note: 'For any other provider that implements the OpenAI Chat Completions API.'
  }
};
const CHAT_PROVIDER_ORDER = ['gemini','groq','openrouter','huggingface','cerebras','custom'];

function defaultChatProfile(providerId){
  const p = CHAT_PROVIDERS[providerId] || CHAT_PROVIDERS.custom;
  return {apiKey:'', baseUrl:p.baseUrl, model:p.model};
}
function loadChatState(){
  try{
    const rawV2 = localStorage.getItem(CHAT_STORAGE_KEY);
    if(rawV2){
      const saved = JSON.parse(rawV2);
      return {
        provider: CHAT_PROVIDERS[saved.provider] ? saved.provider : 'gemini',
        profiles: saved.profiles && typeof saved.profiles === 'object' ? saved.profiles : {},
        autoFallback: !!saved.autoFallback,
        messages: Array.isArray(saved.messages) ? saved.messages : [],
        legacyKeyPurged: !!saved.legacyKeyPurged
      };
    }
    // One-time migration from the original single-provider settings.
    const oldRaw = localStorage.getItem(LEGACY_CHAT_STORAGE_KEY);
    if(oldRaw){
      const old = JSON.parse(oldRaw);
      const oldBase = String(old.baseUrl || '');
      const isGemini = /generativelanguage\.googleapis\.com/i.test(oldBase);
      const provider = isGemini ? 'gemini' : 'custom';
      const profile = defaultChatProfile(provider);
      profile.baseUrl = isGemini ? CHAT_PROVIDERS.gemini.baseUrl : (oldBase || profile.baseUrl);
      profile.model = isGemini ? CHAT_PROVIDERS.gemini.model : (old.model || profile.model);
      // The Gemini key pasted into the conversation is compromised; never migrate that old key.
      if(!isGemini) profile.apiKey = old.apiKey || '';
      const migrated = {
        provider, profiles:{[provider]:profile}, autoFallback:false,
        messages:Array.isArray(old.messages) ? old.messages : [],
        legacyKeyPurged:isGemini && !!old.apiKey
      };
      localStorage.setItem(CHAT_STORAGE_KEY, JSON.stringify(migrated));
      return migrated;
    }
    return {provider:'gemini', profiles:{}, autoFallback:false, messages:[], legacyKeyPurged:false};
  }catch(e){
    return {provider:'gemini', profiles:{}, autoFallback:false, messages:[], legacyKeyPurged:false};
  }
}
function saveChatState(cs){
  try{ localStorage.setItem(CHAT_STORAGE_KEY, JSON.stringify(cs)); }catch(e){}
}
let chatState = loadChatState();

function getChatProfile(providerId){
  const defaults = defaultChatProfile(providerId);
  const saved = chatState.profiles && chatState.profiles[providerId];
  return Object.assign(defaults, saved && typeof saved === 'object' ? saved : {});
}
function getProviderKeyUrl(providerId){
  return (CHAT_PROVIDERS[providerId] || CHAT_PROVIDERS.custom).keyUrl;
}
function renderChatbot(){
  const root = document.getElementById('view-chatbot');
  if(!root) return;
  const activeProfile = getChatProfile(chatState.provider);
  const hasKey = CHAT_PROVIDER_ORDER.some(id => !!String(getChatProfile(id).apiKey || '').trim());
  const providerOptions = CHAT_PROVIDER_ORDER.map(id =>
    `<option value="${id}" ${chatState.provider===id?'selected':''}>${escapeHtml(CHAT_PROVIDERS[id].name)}</option>`
  ).join('');
  root.innerHTML = `
  <div class="card pad" style="padding:0;overflow:hidden">
    <div class="chat-shell">
      <div class="chat-header" style="align-items:flex-start;flex-direction:column">
        <div>
          <h3>✦ AI Coach</h3>
          <p>Multi-provider · Provider-specific API formats · JEE-focused system prompt</p>
        </div>
        <div style="width:100%;display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:8px;align-items:center">
          <select id="chat-provider" aria-label="AI provider" style="min-width:0;width:100%;background:#0d1320;border:1px solid var(--border);border-radius:10px;padding:9px 10px;color:var(--text);font-size:12px">
            ${providerOptions}
          </select>
          <input id="chat-base" type="text" aria-label="API base URL" placeholder="API base URL" value="${escapeHtml(activeProfile.baseUrl||'')}">
          <input id="chat-model" type="text" aria-label="Model ID" placeholder="Model ID" value="${escapeHtml(activeProfile.model||'')}">
          <input id="chat-key" type="password" aria-label="API key" placeholder="Paste this provider's API key" value="${escapeHtml(activeProfile.apiKey||'')}" autocomplete="off">
          <button class="btn small primary" id="chat-save-key" type="button">Save provider</button>
        </div>
        <div style="display:flex;flex-wrap:wrap;gap:10px;align-items:center;width:100%;font-size:11px;color:var(--muted)">
          <label style="display:flex;gap:7px;align-items:center"><input id="chat-auto-fallback" type="checkbox" ${chatState.autoFallback?'checked':''}> Auto-fallback to other saved providers if this one fails</label>
          <span id="chat-provider-note">${escapeHtml(CHAT_PROVIDERS[chatState.provider].note)}</span>
          <a id="chat-key-link" href="${escapeHtml(getProviderKeyUrl(chatState.provider))}" target="_blank" rel="noopener noreferrer" style="color:var(--purple);${getProviderKeyUrl(chatState.provider)?'':'display:none'}">Get API key ↗</a>
        </div>
        <div style="font-size:10px;color:var(--muted)">Each provider has its own saved key and model. Keys are stored locally on this device; never put API keys in GitHub files.</div>
      </div>
      <div class="chat-messages" id="chat-messages"></div>
      <div class="chat-suggestions" id="chat-suggestions">
        <button type="button" data-prompt="Which chapters should I prioritise this week based on typical high-yield PYQ patterns?">High-yield this week</button>
        <button type="button" data-prompt="Explain the concept of rotational dynamics in a JEE-friendly way with common traps.">Rotational dynamics</button>
        <button type="button" data-prompt="Give me a 7-day revision plan for Organic Chemistry focusing on named reactions and mechanisms.">Org Chem 7-day plan</button>
        <button type="button" data-prompt="How do I analyse a mock test: what metrics matter beyond score?">Mock analysis</button>
      </div>
      <div class="chat-status ${hasKey?'ok':''}" id="chat-status">${chatState.legacyKeyPurged?'Old Gemini key discarded for safety. Revoke it and save your replacement key.':(hasKey?'Provider key(s) saved locally.':'Choose a provider, paste its API key, then tap Save provider.')}</div>
      <div class="chat-input-row">
        <textarea id="chat-input" rows="2" placeholder="Ask about a concept, strategy, weak chapter, or paste a problem…"></textarea>
        <button class="btn primary" id="chat-send" type="button">Send ↗</button>
      </div>
    </div>
  </div>`;
  paintMessages();

  document.getElementById('chat-provider').addEventListener('change', e=>{
    chatState.provider = e.target.value;
    const profile = getChatProfile(chatState.provider);
    document.getElementById('chat-base').value = profile.baseUrl || '';
    document.getElementById('chat-model').value = profile.model || '';
    document.getElementById('chat-key').value = profile.apiKey || '';
    document.getElementById('chat-provider-note').textContent = CHAT_PROVIDERS[chatState.provider].note;
    const link = document.getElementById('chat-key-link');
    const keyUrl = getProviderKeyUrl(chatState.provider);
    link.href = keyUrl || '#';
    link.style.display = keyUrl ? 'inline' : 'none';
    saveChatState(chatState);
  });
  document.getElementById('chat-auto-fallback').addEventListener('change', e=>{
    chatState.autoFallback = !!e.target.checked;
    saveChatState(chatState);
  });
  document.getElementById('chat-save-key').onclick = ()=>{
    const providerId = chatState.provider;
    const profile = getChatProfile(providerId);
    profile.apiKey = document.getElementById('chat-key').value.trim();
    profile.baseUrl = (document.getElementById('chat-base').value.trim() || CHAT_PROVIDERS[providerId].baseUrl).replace(/\/$/,'');
    profile.model = document.getElementById('chat-model').value.trim() || CHAT_PROVIDERS[providerId].model;
    chatState.profiles[providerId] = profile;
    chatState.legacyKeyPurged = false;
    saveChatState(chatState);
    const st = document.getElementById('chat-status');
    st.textContent = profile.apiKey ? `${CHAT_PROVIDERS[providerId].name} credentials saved on this device.` : 'Provider key cleared.';
    st.className = 'chat-status ' + (profile.apiKey ? 'ok' : '');
    toast(profile.apiKey ? 'Provider credentials saved locally.' : 'Provider key cleared.');
  };
  document.getElementById('chat-send').onclick = sendChat;
  document.getElementById('chat-input').addEventListener('keydown', e=>{
    if(e.key==='Enter' && !e.shiftKey){ e.preventDefault(); sendChat(); }
  });
  document.querySelectorAll('#chat-suggestions button').forEach(b=>{
    b.onclick = ()=>{ document.getElementById('chat-input').value = b.dataset.prompt; sendChat(); };
  });
}

function escapeHtml(s){
  return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}
function paintMessages(){
  const box = document.getElementById('chat-messages');
  if(!box) return;
  if(!chatState.messages.length){
    box.innerHTML = `<div class="msg system">Start a conversation. Your request is sent directly to the provider you choose. Chat history is stored only in this app's localStorage.</div>`;
    return;
  }
  box.innerHTML = chatState.messages.map(m=>{
    const role = m.role === 'user' ? 'You' : (m.role === 'assistant' ? 'Coach' : 'System');
    const cls = m.role === 'user' ? 'user' : (m.role === 'assistant' ? 'assistant' : 'system');
    return `<div class="msg ${cls}"><div class="role">${role}</div>${formatMsg(m.content)}</div>`;
  }).join('');
  box.scrollTop = box.scrollHeight;
}
function formatMsg(text){
  let t = escapeHtml(text);
  t = t.replace(/\*\*(.+?)\*\*/g,'<b>$1</b>');
  t = t.replace(/`([^`]+)`/g,'<code style="background:#0006;padding:1px 5px;border-radius:4px;font-size:12px">$1</code>');
  t = t.replace(/\n/g,'<br>');
  return t;
}
function messageText(content){
  if(typeof content === 'string') return content;
  if(Array.isArray(content)) return content.map(part => typeof part === 'string' ? part : (part && (part.text || part.content) || '')).join('');
  if(content && typeof content === 'object') return content.text || content.content || JSON.stringify(content);
  return '';
}
function getProviderError(data, status){
  return data?.error?.message || data?.message || data?.detail || data?.error?.status || `HTTP ${status}`;
}
async function callChatProvider(providerId, messages){
  const provider = CHAT_PROVIDERS[providerId];
  const profile = getChatProfile(providerId);
  if(!profile.apiKey || !profile.apiKey.trim()) throw new Error('No API key saved');
  const base = (profile.baseUrl || provider.baseUrl).replace(/\/$/,'');
  let url, headers = {'Content-Type':'application/json'}, payload;

  if(provider.kind === 'gemini'){
    url = `${base}/models/${encodeURIComponent(profile.model || provider.model)}:generateContent`;
    headers['x-goog-api-key'] = profile.apiKey.trim();
    const contents = messages.filter(m=>m.role==='user'||m.role==='assistant').map(m=>({
      role:m.role==='assistant'?'model':'user',
      parts:[{text:messageText(m.content)}]
    }));
    payload = {
      systemInstruction:{parts:[{text:DEFAULT_SYSTEM}]},
      contents,
      generationConfig:{temperature:0.55,maxOutputTokens:1600}
    };
  }else{
    url = /\/chat\/completions$/i.test(base) ? base : `${base}/chat/completions`;
    headers.Authorization = 'Bearer ' + profile.apiKey.trim();
    if(providerId === 'openrouter'){
      headers['HTTP-Referer'] = 'https://loadout.local';
      headers['X-Title'] = 'Loadout JEE Performance Engine';
    }
    payload = {
      model:profile.model || provider.model,
      messages:[{role:'system',content:DEFAULT_SYSTEM},...messages.filter(m=>m.role==='user'||m.role==='assistant').map(m=>({role:m.role,content:messageText(m.content)}))],
      temperature:0.55,
      max_tokens:1600
    };
  }

  let response;
  try{
    response = await fetch(url,{method:'POST',headers,body:JSON.stringify(payload)});
  }catch(err){
    throw new Error(`Network/CORS failure: ${err.message || 'request blocked'}`);
  }
  const data = await response.json().catch(()=>({}));
  if(!response.ok) throw new Error(getProviderError(data,response.status));
  let answer = '';
  if(provider.kind === 'gemini'){
    answer = (data.candidates || []).flatMap(c=>(c.content?.parts || []).map(p=>p.text || '')).join('\n').trim();
    if(!answer && data.promptFeedback?.blockReason) throw new Error(`Prompt blocked: ${data.promptFeedback.blockReason}`);
  }else{
    answer = messageText(data.choices?.[0]?.message?.content) || data.output_text || data.response || '';
  }
  if(!answer) throw new Error('Provider returned an empty response or an unsupported response format');
  return answer;
}
function getChatProviderCandidates(){
  const selected = chatState.provider;
  const configured = CHAT_PROVIDER_ORDER.filter(id=>!!String(getChatProfile(id).apiKey||'').trim());
  if(!chatState.autoFallback) return configured.includes(selected) ? [selected] : [];
  return [selected,...CHAT_PROVIDER_ORDER.filter(id=>id!==selected)].filter((id,index,arr)=>configured.includes(id)&&arr.indexOf(id)===index);
}
async function sendChat(){
  const input = document.getElementById('chat-input');
  if(!input) return;
  const text = (input.value||'').trim();
  if(!text) return;
  const candidates = getChatProviderCandidates();
  if(!candidates.length){
    const st = document.getElementById('chat-status');
    st.textContent = 'Save an API key for the selected provider first. Turn on auto-fallback only after saving additional provider keys.';
    st.className = 'chat-status err';
    toast('API key required');
    return;
  }
  input.value = '';
  chatState.messages.push({role:'user',content:text});
  saveChatState(chatState);
  paintMessages();
  const box = document.getElementById('chat-messages');
  const typing = document.createElement('div');
  typing.className = 'msg assistant';
  typing.id = 'typing-ind';
  typing.innerHTML = `<div class="role">Coach</div><div class="typing"><span></span><span></span><span></span></div>`;
  box.appendChild(typing);
  box.scrollTop = box.scrollHeight;

  const requestHistory = chatState.messages.slice(-20);
  const failures = [];
  let completed = false;
  for(let i=0;i<candidates.length;i++){
    const providerId = candidates[i];
    try{
      const answer = await callChatProvider(providerId,requestHistory);
      document.getElementById('typing-ind')?.remove();
      chatState.messages.push({role:'assistant',content:answer});
      const st = document.getElementById('chat-status');
      st.textContent = `Reply received via ${CHAT_PROVIDERS[providerId].name}${i>0?` · fallback ${i+1}/${candidates.length}`:''}.`;
      st.className = 'chat-status ok';
      completed = true;
      break;
    }catch(err){
      failures.push(`${CHAT_PROVIDERS[providerId].name}: ${err.message}`);
      if(!chatState.autoFallback) break;
    }
  }
  if(!completed){
    document.getElementById('typing-ind')?.remove();
    const details = failures.map((f,i)=>`${i+1}. ${f}`).join('\n');
    const corsHint = failures.some(f=>/CORS|Network\/CORS|Failed to fetch/i.test(f))
      ? '\n\nA browser/Android WebView CORS restriction may be blocking that provider. Try another provider or use a small private proxy; this app currently makes direct device-to-provider requests.' : '';
    chatState.messages.push({role:'assistant',content:`⚠️ All attempted providers failed:\n${details}${corsHint}`});
    const st = document.getElementById('chat-status');
    st.textContent = failures[failures.length-1] || 'All configured providers failed.';
    st.className = 'chat-status err';
  }
  saveChatState(chatState);
  paintMessages();
}

// Clear chat history without deleting saved provider profiles or API credentials.
window.clearLoadoutChat = function(){
  chatState.messages = [];
  saveChatState(chatState);
  if(currentView==='chatbot') renderChatbot();
  toast('Chat history cleared');
};
